type Matrix<T> = Vec<Vec<T>>;

fn broadcast(a: Vec<i8>, shape: Vec<u8>) -> Matrix<i8> {
    let r = shape[0] as usize;
    let c = shape[1] as usize;
    let len = a.len();

    // Per problem assumptions, length of a equals either r or c.
    // If r == len, broadcast a as column vector along columns.
    if r == len {
        // Each row i copies a[i] across all columns
        (0..r)
            .map(|i| vec![a[i]; c])
            .collect()
    } else {
        // Otherwise c == len, broadcast a as row vector along rows.
        // Each row is a clone of a
        (0..r)
            .map(|_| a.clone())
            .collect()
    }
}